wrongCode:
// In Node.js / Express
const PORT = process.env.PORT || 3000;
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Server running on port ${PORT}`);
});

# Or in Python FastAPI / Uvicorn
uvicorn.run(app, host="127.0.0.1", port=8000)

fixedCode:
// In Node.js / Express
const PORT = process.env.PORT || 3000;
// Omit host or specify '0.0.0.0'
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Server running on 0.0.0.0:${PORT}`);
});

# Or in Python FastAPI / Uvicorn
uvicorn.run(app, host="0.0.0.0", port=8000)

wrongCode:
// HARDCODED - NEVER DO THIS IN PRODUCTION
const pool = new Pool({
  user: 'postgres',
  host: 'localhost', // FAILS in cloud container!
  database: 'mydb',
  password: 'mypassword123',
  port: 5432,
});

fixedCode:
// CORRECT - Dynamic environment variables from Zerops
const pool = new Pool({
  user: process.env.DB_USER || process.env.db_user,
  host: process.env.DB_HOST || process.env.db_hostname,
  database: process.env.DB_NAME || process.env.db_name,
  password: process.env.DB_PASSWORD || process.env.db_password,
  port: Number(process.env.DB_PORT || process.env.db_port) || 5432,
});

// Or using connection string:
const connectionString = process.env.DATABASE_URL;

wrongCode:
// Missing dedicated health endpoint or requiring authentication for /healthz
app.use(authMiddleware); // Blocks all routes, including /healthz with 401 Unauthorized!
app.get('/healthz', (req, res) => res.send('OK'));

fixedCode:
// Exclude healthcheck from authentication middleware
app.get('/healthz', (req, res) => {
  res.status(200).json({ status: 'healthy', timestamp: new Date().toISOString() });
});

// Apply auth middleware AFTER health check
app.use(authMiddleware);
